// Golden hour puppy — make.fun ai-happy-01 entry.
// The picture (JPEG bytes, base64) is embedded below and written to /output/entry.png.
// Run locally: mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';

// The embedded picture is a 1024x1024 JPEG of a smiling golden retriever
// puppy in a wildflower meadow at golden hour — base64 on one line below,
// filled in at build time so the program stays a single self-contained file.
const IMAGE_B64 = "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
writeFileSync(join(outDir, 'entry.png'), Buffer.from(IMAGE_B64, 'base64'));
